const input = $json.body || $json;
const lower = (v) => String(v || '').toLowerCase();
const pain = lower(input.pain);
const interest = lower(input.interest);
let score = 20;
if (['500-2000','2000+'].includes(input.company_size)) score += 18;
if (['this-week','this-month'].includes(input.timeline)) score += 20;
if (['1000-3000','3000+'].includes(input.budget)) score += 18;
['lead','ads','facebook','meta','google ads','crm','email','follow up','follow-up','sales','website'].forEach(k => {
  if (pain.includes(k) || interest.includes(k)) score += 4;
});
score = Math.min(score, 100);
const tier = score >= 80 ? 'Hot lead' : score >= 55 ? 'Warm lead' : 'Nurture lead';
const owner = score >= 80 ? 'Sales closer' : score >= 55 ? 'Sales development rep' : 'Marketing nurture list';
const stage = score >= 80 ? 'Book discovery call today' : score >= 55 ? 'Send qualification email' : 'Add to weekly nurture campaign';
const first = String(input.full_name || 'there').split(' ')[0];
return [{ json: {
  status: 'success',
  workflow: 'Marketing Leads Automation',
  lead: input,
  qualification: { score, tier, owner, stage },
  business_actions: [
    `Add lead to Google Sheet: ${tier}, score ${score}`,
    `Create CRM task for ${owner}`,
    score >= 80 ? 'Send instant sales alert to Slack/email' : 'Add lead to nurture/follow-up queue',
    'Generate personalized follow-up email'
  ],
  sheet_row: {
    created_at: new Date().toISOString(),
    name: input.full_name || '',
    company: input.company || '',
    email: input.email || '',
    phone: input.phone || '',
    source: input.source || '',
    interest: input.interest || '',
    company_size: input.company_size || '',
    budget: input.budget || '',
    timeline: input.timeline || '',
    score,
    tier,
    owner,
    next_action: stage,
    pain: input.pain || ''
  },
  sales_notification: `New ${tier}: ${input.full_name || ''} from ${input.company || ''}\nScore: ${score}/100\nInterest: ${input.interest || ''}\nSource: ${input.source || ''}\nNext action: ${stage}\nPain point: ${input.pain || ''}`,
  follow_up_email: {
    to: input.email || '',
    subject: `Thanks for your interest in marketing automation, ${first}`,
    body: `Hi ${first},\n\nThanks for reaching out about ${input.interest || 'marketing automation'}. Based on what you shared, the best next step is: ${stage}.\n\nI can help build an automation that captures leads, scores them, saves them to a tracker, and notifies the sales team so follow-ups do not get missed.\n\nBest,\nYour Name`
  }
}}];
